$ErrorActionPreference = 'Stop'
Set-Location -LiteralPath $PSScriptRoot
function Run-Git { & git @args; if ($LASTEXITCODE -ne 0) { throw "git $($args[0]) failed ($LASTEXITCODE)" } }
if ((Run-Git branch --show-current) -ne 'main') { throw 'Expected main' }
$base = '751f44d780d8842e326b960a17780d03c7c1ff83'
$desired = '3062093746e97f0e791e8a547a4e97ae12380027'
$head = Run-Git rev-parse HEAD
if ($head -eq $base) {
    if (Run-Git diff --cached --name-only) { throw 'Review existing staged changes first' }
    $patch = [IO.Path]::GetTempFileName()
    try {
        [IO.File]::WriteAllBytes($patch, [Convert]::FromBase64String(''))
        Run-Git apply --cached --check -- $patch
        Run-Git apply --cached -- $patch
    } finally { [IO.File]::Delete($patch) }
    if ((Run-Git rev-parse ':README.md') -ne $desired) { throw 'Unexpected staged README' }
    Run-Git commit -m 'Document SQL syntax support and planning TODOs'
}
$head = Run-Git rev-parse HEAD
if ((Run-Git rev-parse 'HEAD^') -ne $base -or (Run-Git rev-parse 'HEAD:README.md') -ne $desired -or (Run-Git diff --name-only $base $head) -ne 'README.md') { throw 'Unexpected main commit' }
Run-Git push origin "${head}:refs/heads/main"
$remote = Run-Git ls-remote --exit-code origin refs/heads/main
if (($remote -split '\s+')[0] -ne $head) { throw 'GitHub main verification failed' }
Write-Host "Verified GitHub main at $head"
